window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7ff72a273f13b64b"]={"versions": [{"id": "FIG-7ff72a273f13b64b", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des dynamischen Verhaltens beim Zustandswechsel einer Funktionsgruppe (<em>Change Function Group State</em>) im Architektur-Kontext der AUTOSAR Adaptive Platform (AP). Das Szenario veranschaulicht das Zusammenspiel zwischen Steuerungslogik, Prozesslebenszyklus-Verwaltung und Plattform-Überwachung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien und Entitäten:</p>\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» :State Management</code> (SM): Initiator des Zustandswechsels.\n</li><li><code>«aapFunctionalCluster» :Execution Management</code> (EM): Zentrale Steuerungsinstanz für Prozessstarts, Terminierung und Statusverwaltung.\n</li><li><code>:Operating System</code>: POSIX-basiertes Betriebssystem zur Prozessinstanziierung und Signalverarbeitung.\n</li><li><code>old: Adaptive Application 0..*</code>: Bestehende, zu terminierende Anwendungsprozesse der vorherigen Konfiguration.\n</li><li><code>new: Adaptive Application 0..*</code>: Neu zu startende Anwendungsprozesse der Zielkonfiguration.\n</li><li><code>«aapFunction...» :Core</code> (ara::core): Basislaufzeitbibliothek der Adaptive Platform.\n</li><li><code>«aapFunctionalCluster» :Platform Health Management</code> (PHM): Plattformgesundheits- und Überwachungsinstanz.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li><code>SetState(FunctionGroupState)</code>: Anforderung des Zustandswechsels an EM.\n</li><li><code>startStateTransition(old, new)</code>: Ankündigung des Zustandswechsels an PHM.\n</li><li><code>determineObsoleteProcesses()</code>: EM-interne Bestimmung zu beendender Prozesse.\n</li><li><code>processTerminating(process)</code>: Benachrichtigung an PHM vor Beendigung eines Prozesses.\n</li><li><code>stopSupervision()</code>: PHM-interne Deaktivierung der Überwachung.\n</li><li><code>SIGTERM()</code>: POSIX-Terminierungssignal an die alte Anwendung.\n</li><li><code>Deinitialize()</code>: Herunterfahren der Core-Komponenten durch die Anwendung.\n</li><li><code>determineProcessesToStart()</code>: EM-interne Ermittlung der neu zu startenden Prozesse.\n</li><li><code>exec()</code>: POSIX-Systemaufruf zum Starten des neuen Prozesses.\n</li><li><code>main()</code>: Einstiegspunkt der neuen Anwendung.\n</li><li><code>Initialize()</code>: Initialisierung der Core-Komponenten.\n</li><li><code>ReportExecutionState(kRunning)</code>: Ausführungsstatusmeldung der Anwendung an EM.\n</li><li><code>processStarted(process, timestamp)</code>: Benachrichtigung an PHM über den gestarteten Prozess.\n</li><li><code>startAliveSupervision()</code>: PHM-interne Aktivierung der Alive-Überwachung.\n</li><li><code>ReportCheckpoint()</code>: Regelmäßige Checkpoint-Meldung der Anwendung an PHM.\n</li><li>Asynchrone/synchrone Rückmeldung (gestrichelter Pfeil) an SM nach Abschluss des Übergangs.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initiierung</strong>: <code>State Management</code> ruft synchron <code>SetState(FunctionGroupState)</code> am <code>Execution Management</code> auf. EM informiert PHM über <code>startStateTransition(old, new)</code> und ermittelt intern über <code>determineObsoleteProcesses()</code> die obsoleten Prozesse.\n</li><li><strong>Terminierung (<code>loop Terminate obsolete Processes</code>)</strong>:\n<ul class=\"fig-list\"><li>Für jeden obsoleten Prozess sendet EM <code>processTerminating(process)</code> an PHM, woraufhin PHM intern <code>stopSupervision()</code> ausführt.\n</li><li>EM sendet <code>SIGTERM()</code> an den Prozess <code>old: Adaptive Application 0..*</code>.\n</li><li>Der Prozess ruft vor dem Beenden <code>Deinitialize()</code> an <code>:Core</code> auf und terminiert anschließend (gekennzeichnet durch das Löschkreuz <code>X</code>).\n</li></ul>\n</li><li><strong>Prozessstart (<code>loop Start Processes</code>)</strong>:\n<ul class=\"fig-list\"><li>EM ermittelt über <code>determineProcessesToStart()</code> die zu startenden Prozesse.\n</li><li>Für jeden Prozess führt EM einen Systemaufruf <code>exec()</code> an das <code>:Operating System</code> aus.\n</li><li>Das Betriebssystem erzeugt die Instanz <code>new: Adaptive Application 0..*</code> und ruft deren <code>main()</code> auf.\n</li><li>Die Anwendung führt <code>Initialize()</code> an <code>:Core</code> aus und meldet ihren Status via <code>ReportExecutionState(kRunning)</code> an EM.\n</li><li>EM meldet an PHM <code>processStarted(process, timestamp)</code>, woraufhin PHM intern <code>startAliveSupervision()</code> startet.\n</li><li>Die laufende Anwendung meldet periodisch ihren Fortschritt über <code>ReportCheckpoint()</code> an PHM.\n</li></ul>\n</li><li><strong>Abschluss</strong>: Nach Abarbeitung aller Starts und Terminierungen sendet EM eine Antwort an SM zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der Ablauf definiert das Standard-Zusammenspiel bei Zustandsübergängen von Funktionsgruppen gemäß Manifest-Konfiguration (<code>StartupConfig</code>).\n</li><li>Kritische Sequenzierung: PHM muss vor dem Senden von <code>SIGTERM</code> benachrichtigt werden (<code>processTerminating</code>), um Fehlalarme bei der Überwachung während des Shutdowns zu verhindern.\n</li><li>Die Überwachung des Shutdowns erfolgt über EM-seitig konfigurierte Timeouts (<code>StartupConfig.timeout</code>).\n</li><li>Neue Anwendungen müssen sich nach dem Start explizit via <code>ReportExecutionState(kRunning)</code> bei EM melden, bevor die Alive-Überwachung durch PHM aktiv wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-324a38c1530a3a9d", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des dynamischen Verhaltens beim Zustandswechsel einer Funktionsgruppe (<em>Change Function Group State</em>) im Architektur-Kontext der AUTOSAR Adaptive Platform (AP). Das Szenario veranschaulicht das Zusammenspiel zwischen Steuerungslogik, Prozesslebenszyklus-Verwaltung und Plattform-Überwachung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien und Entitäten:</p>\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» :State Management</code> (SM): Initiator des Zustandswechsels.\n</li><li><code>«aapFunctionalCluster» :Execution Management</code> (EM): Zentrale Steuerungsinstanz für Prozessstarts, Terminierung und Statusverwaltung.\n</li><li><code>:Operating System</code>: POSIX-basiertes Betriebssystem zur Prozessinstanziierung und Signalverarbeitung.\n</li><li><code>old: Adaptive Application 0..*</code>: Bestehende, zu terminierende Anwendungsprozesse der vorherigen Konfiguration.\n</li><li><code>new: Adaptive Application 0..*</code>: Neu zu startende Anwendungsprozesse der Zielkonfiguration.\n</li><li><code>«aapFunction...» :Core</code> (ara::core): Basislaufzeitbibliothek der Adaptive Platform.\n</li><li><code>«aapFunctionalCluster» :Platform Health Management</code> (PHM): Plattformgesundheits- und Überwachungsinstanz.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Interaktionen (mit expliziter Kennzeichnung informativer Anteile):</p>\n<ul class=\"fig-list\"><li><code>SetState(FunctionGroupState)</code>: Normative Anforderung des Zustandswechsels an EM.\n</li><li><code>«aapInformative» startStateTransition(old, new)</code>: Informative Ankündigung des Zustandswechsels an PHM.\n</li><li><code>«aapInformative» determineObsoleteProcesses()</code>: Informativer EM-interner Aufruf zur Bestimmung zu beendender Prozesse.\n</li><li><code>processTerminating(process) «aapInformative»</code>: Informative Benachrichtigung an PHM vor Beendigung eines Prozesses.\n</li><li><code>«aapInformative» stopSupervision()</code>: Informativer PHM-interner Aufruf zur Deaktivierung der Überwachung.\n</li><li><code>SIGTERM()</code>: Normatives POSIX-Terminierungssignal an die alte Anwendung.\n</li><li><code>Deinitialize()</code>: Normatives Herunterfahren der Core-Komponenten durch die Anwendung.\n</li><li><code>«aapInformative» determineProcessesToStart()</code>: Informativer EM-interner Aufruf zur Ermittlung der neu zu startenden Prozesse.\n</li><li><code>exec() «aapInformative»</code>: Informativer Betriebssystemaufruf zum Starten des neuen Prozesses.\n</li><li><code>main() «aapInformative»</code>: Informativer Programmeinstiegspunkt der neuen Anwendung.\n</li><li><code>Initialize()</code>: Normative Initialisierung der Core-Komponenten.\n</li><li><code>ReportExecutionState(kRunning)</code>: Normative Ausführungsstatusmeldung der Anwendung an EM.\n</li><li><code>processStarted(process, timestamp) «aapInformative»</code>: Informative Benachrichtigung an PHM über den gestarteten Prozess.\n</li><li><code>«aapInformative» startAliveSupervision()</code>: Informativer PHM-interner Aufruf zur Aktivierung der Alive-Überwachung.\n</li><li><code>ReportCheckpoint()</code>: Normative Checkpoint-Meldung der Anwendung an PHM.\n</li><li>Asynchrone/synchrone Rückmeldung (gestrichelter Pfeil) an SM nach Abschluss des Übergangs.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initiierung</strong>: <code>State Management</code> ruft synchron <code>SetState(FunctionGroupState)</code> am <code>Execution Management</code> auf. EM informiert PHM über <code>startStateTransition(old, new)</code> und ermittelt intern über <code>determineObsoleteProcesses()</code> die obsoleten Prozesse.\n</li><li><strong>Terminierung (<code>loop Terminate obsolete Processes</code>)</strong>:\n<ul class=\"fig-list\"><li>Für jeden obsoleten Prozess sendet EM <code>processTerminating(process)</code> an PHM, woraufhin PHM intern <code>stopSupervision()</code> ausführt.\n</li><li>EM sendet <code>SIGTERM()</code> an den Prozess <code>old: Adaptive Application 0..*</code>.\n</li><li>Der Prozess ruft vor dem Beenden <code>Deinitialize()</code> an <code>:Core</code> auf und terminiert anschließend (gekennzeichnet durch das Löschkreuz <code>X</code>).\n</li></ul>\n</li><li><strong>Prozessstart (<code>loop Start Processes</code>)</strong>:\n<ul class=\"fig-list\"><li>EM ermittelt über <code>determineProcessesToStart()</code> die zu startenden Prozesse.\n</li><li>Für jeden Prozess führt EM einen Systemaufruf <code>exec()</code> an das <code>:Operating System</code> aus.\n</li><li>Das Betriebssystem erzeugt die Instanz <code>new: Adaptive Application 0..*</code> und ruft deren <code>main()</code> auf.\n</li><li>Die Anwendung führt <code>Initialize()</code> an <code>:Core</code> aus und meldet ihren Status via <code>ReportExecutionState(kRunning)</code> an EM.\n</li><li>EM meldet an PHM <code>processStarted(process, timestamp)</code>, woraufhin PHM intern <code>startAliveSupervision()</code> startet.\n</li><li>Die laufende Anwendung meldet periodisch ihren Fortschritt über <code>ReportCheckpoint()</code> an PHM.\n</li></ul>\n</li><li><strong>Abschluss</strong>: Nach Abarbeitung aller Starts und Terminierungen sendet EM eine Antwort an SM zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Explizite Trennung zwischen normativen Schnittstellenanforderungen und informativen Implementierungsdetails (<code>«aapInformative»</code>):\n<ul class=\"fig-list\"><li>Normativ verbindlich sind die Schnittstellenaufrufe <code>SetState</code>, <code>SIGTERM</code>, <code>Deinitialize</code>, <code>Initialize</code>, <code>ReportExecutionState(kRunning)</code> und <code>ReportCheckpoint</code>.\n</li><li>Als informativ (<code>«aapInformative»</code>) deklariert sind die internen Kontrollflüsse (<code>determineObsoleteProcesses</code>, <code>determineProcessesToStart</code>, <code>stopSupervision</code>, <code>startAliveSupervision</code>) sowie die Interaktionen mit dem OS (<code>exec</code>, <code>main</code>) und die internen Interaktionsnachrichten zwischen EM und PHM (<code>startStateTransition</code>, <code>processTerminating</code>, <code>processStarted</code>).\n</li></ul>\n</li><li>Die zeitliche Reihenfolge (PHM-Benachrichtigung vor <code>SIGTERM</code>, Überwachung nach <code>ReportExecutionState(kRunning)</code>) bleibt für eine fehlerfreie Koordination architektonisch maßgeblich.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7ff72a273f13b64b", "to": "FIG-324a38c1530a3a9d", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Stereotyp «aapInformative» an folgenden internen Methodenaufrufen und Interaktionen ergänzt:\n<ul class=\"fig-list\"><li><code>startStateTransition(old, new)</code>\n</li><li><code>determineObsoleteProcesses()</code>\n</li><li><code>processTerminating(process)</code>\n</li><li><code>stopSupervision()</code>\n</li><li><code>determineProcessesToStart()</code>\n</li><li><code>exec()</code>\n</li><li><code>main()</code>\n</li><li><code>processStarted(process, timestamp)</code>\n</li><li><code>startAliveSupervision()</code>\n</li></ul>\n</li></ul>"}]};
